export const TEMPLATE_STEERING_MD: string = "# BIOS // NECROMANCER (`cmos-cloud-bios`) — Template Steering\n\n- **Mode:** Mode A native website inside GenUI Studio, previewed at `/preview/cmos-cloud-bios`.\n- **Spec:** `.kiro/specs/cmos-cloud-bios/` (`requirements.md`, `design.md`, `tasks.md`).\n- **Scoped rules:** `.kiro/steering/cmos-bios-rules.md`.\n- **Engine:** `lib/cmos/engine.ts` owns all register state. UI and 3D components read the shared store and never keep their own copy.\n- **Compiler:** `lib/cmos/compiler.ts` is pure and deterministic. Every artifact header carries the CMOS checksum.\n- **Visuals:** 16-colour VGA palette only (`#0000AA #FFFF55 #FFFFFF #00AAAA #AA0000 #000000`), double-line frames, zero radius, instant selection inversion.\n- **Safety:** register writes are Zod validated. Invalid streamed packets load fail-safe BIOS defaults. No raw HTML, `eval` or secrets in generated files.\n";

export const TEMPLATE_SKILL_MD: string = "---\nname: cmos-cloud-bios\ndescription: Use when building, extending or remixing the BIOS // NECROMANCER template, an Award BIOS setup utility that maps hardware registers to cloud infrastructure and compiles docker-compose.yml, vercel.json and main.tf.\n---\n\n# BIOS // NECROMANCER Skill\n\n## What this template is\nA 1994 Award Modular BIOS setup utility, a 3D motherboard digital twin and a landing-page mode, all driven by one CMOS register store. Register changes recompute a deterministic cloud topology and simulated telemetry, and recompile three infrastructure files.\n\n## Key modules\n- `lib/cmos/engine.ts`: `CmosConfigSchema`, presets, `deriveCloudTopology`, `simulateCmos`, `applyCloudPatch`, `cmosReducer`, `createCmosStore`.\n- `lib/cmos/compiler.ts`: `compileCmos(config, { projectName, functionsGlob })` returns artifacts, notes and the FSK manifest.\n- `lib/cmos/audio.ts`: `getCmosAudio()` for beeps, the alarm and `transmit()`. `encodeFskSamples()` is pure and testable.\n- `components/`: `CmosWorkstationShell` (root), `PostBootSequence`, `AwardBiosMenuGrid`, `Motherboard3DTwin`, `HardwareTelemetryMonitor`, `IaCCodeCompilerOutput`, `AcousticModemOscilloscope`, `DevToolsHeroSection`, `CmosRegisterPacket`.\n\n## Register → cloud mapping (summary)\n| Register | Cloud setting |\n| --- | --- |\n| FSB × multiplier | vCPU per instance and concurrency |\n| Vcore | Autoscaling ceiling (4 × 2^((mV − 2800)/100)) |\n| DRAM | Function memory (RAM × 32) |\n| IDE Primary Master / RAID / Primary Slave | PostgreSQL class / read replicas / pgvector |\n| IDE Secondary Master | Redis tier |\n| PCI slots + bus clock | API gateway throttling, edge CDN + WAF, webhook queue |\n| Power management / standby / watchdog | Warm pool / scale-in delay / timeout |\n| Budget cap, fan RPM, warning temperature | AWS Budget, target utilization, DDoS limit per IP |\n| Time zone | AWS + Vercel region |\n\n## Rules for changes\n1. Add new registers to `CmosConfigSchema` first, then map them in `deriveCloudTopology`, then expose them in `components/bios-menus.ts`.\n2. Keep the compiler deterministic: no clocks, randomness or environment reads.\n3. Stay inside the VGA palette and keep keyboard parity for every mouse action.\n4. Costs are estimates from public list prices. Never present them as quotes.\n\n## Install\n```bash\nnpx genui-studio add cmos-cloud-bios\n```\n";

export const TEMPLATE_KIRO_POWER_MD: string = "---\nname: \"cmos-cloud-bios\"\ndisplayName: \"BIOS // NECROMANCER — 1994 CMOS Utility & 3D Motherboard Cloud Compiler\"\ndescription: \"Award BIOS setup utility that compiles real cloud infrastructure (docker-compose.yml, vercel.json, main.tf) from CMOS registers, with a 3D motherboard twin and an FSK modem.\"\nkeywords: [\"bios\", \"cmos\", \"iac\", \"terraform\", \"docker-compose\", \"vercel\", \"react-three-fiber\", \"web-audio\"]\n---\n\n# BIOS // NECROMANCER Kiro Power\n\n## Onboarding\n1. Install the template: `npx genui-studio add cmos-cloud-bios`.\n2. Read `.kiro/specs/cmos-cloud-bios/design.md` for the register → cloud mapping and the simulator model.\n3. Steering for this directory lives in `.kiro/steering/cmos-bios-rules.md`.\n\n## Common tasks\n- **Add a register:** extend `CmosConfigSchema`, map it in `deriveCloudTopology`, add a row in `components/bios-menus.ts`, then run the property tests.\n- **Change pricing:** edit `PRICING`, `DRIVE_SPECS` and `CACHE_SPECS` in `lib/cmos/engine.ts`.\n- **Add an artifact:** add a builder in `lib/cmos/compiler.ts` and include it in `compileCmos`.\n- **Verify:** `pnpm --filter @genui-studio/templates exec vitest run src/__tests__/cmos-bios.pbt.test.ts`.\n\n## Guarantees\n- The same registers always compile to byte-identical files.\n- Invalid streamed register packets load fail-safe BIOS defaults instead of crashing.\n- Audio starts only after a user gesture and can be muted.\n";

