    "content": "{\n  \"slug\": \"cmos-cloud-bios\",\n  \"id\": \"cmos-cloud-bios\",\n  \"name\": \"cmos-cloud-bios\",\n  \"title\": \"BIOS // NECROMANCER — 1994 CMOS Utility & 3D Motherboard Cloud Compiler\",\n  \"description\": \"Flagship Website #3: an Award Modular BIOS setup utility that configures real cloud infrastructure. Tune clock multipliers, RAID, IRQ lines and power budgets, watch simulated cost, P99 latency and thermals react on a 3D motherboard twin, then compile docker-compose.yml, vercel.json and main.tf or transmit the config as FSK modem audio.\",\n  \"mode\": \"native\",\n  \"version\": \"1.0.0\",\n  \"author\": \"GenUI Studio\",\n  \"license\": \"MIT\",\n  \"tier\": \"free\",\n  \"priceUsd\": 0,\n  \"category\": \"DevTools / Infrastructure\",\n  \"tags\": [\"3D / WebGL\", \"B2B SaaS\", \"GenUI Verified\"],\n  \"verified\": true,\n  \"featured\": true,\n  \"immersiveExperience\": true,\n  \"theme\": {\n    \"defaultColorScheme\": \"dark\",\n    \"accentColor\": \"#FFFF55\",\n    \"surfaceBg\": \"#0000AA\",\n    \"surfaceElevated\": \"#000000\",\n    \"textColor\": \"#FFFFFF\",\n    \"mutedColor\": \"#00AAAA\",\n    \"displayFont\": \"\\\"VT323\\\", \\\"Space Mono\\\", ui-monospace, monospace\",\n    \"bodyFont\": \"\\\"VT323\\\", \\\"Space Mono\\\", ui-monospace, monospace\",\n    \"borderRadius\": \"0\"\n  },\n  \"pages\": [\n    {\n      \"id\": \"home\",\n      \"slug\": \"home\",\n      \"title\": \"BIOS // NECROMANCER · CMOS Setup\",\n      \"route\": \"/\",\n      \"description\": \"POST boot, split-screen Award BIOS with 3D motherboard twin, and a hardware landing-page mode.\",\n      \"sections\": [\n        \"CmosWorkstationShell\",\n        \"PostBootSequence\",\n        \"AwardBiosMenuGrid\",\n        \"Motherboard3DTwin\",\n        \"HardwareTelemetryMonitor\",\n        \"IaCCodeCompilerOutput\",\n        \"AcousticModemOscilloscope\",\n        \"DevToolsHeroSection\"\n      ]\n    }\n  ],\n  \"remixPresets\": [\n    {\n      \"id\": \"ai-agent-overclock\",\n      \"label\": \"Stream Preset: AI Agent Cluster Overclock (Max GPU PCIe + High Memory Bus)\",\n      \"description\": \"Loads 4 vCPU, 128 MB RAM bus, NVMe RAID 10 with pgvector, a 6 GB cache and dual API gateways.\",\n      \"prompt\": \"Stream Preset: AI Agent Cluster Overclock (Max GPU PCIe + High Memory Bus)\"\n    },\n    {\n      \"id\": \"indie-undervolt\",\n      \"label\": \"Stream Preset: Zero-Cost Indie Hacker Undervolt (Strict FinOps Spend Cap)\",\n      \"description\": \"Loads a stateless scale-to-zero profile with a single gateway and a $25 spend cap.\",\n      \"prompt\": \"Stream Preset: Zero-Cost Indie Hacker Undervolt (Strict FinOps Spend Cap)\"\n    },\n    {\n      \"id\": \"corrupted-register-packet\",\n      \"label\": \"Inject Corrupted Voltage / Negative IRQ Packet\",\n      \"description\": \"Streams a register packet with negative Vcore and invalid IRQs. The catalog clamps it, the CMOS engine rejects it, and the BIOS loads fail-safe defaults without crashing.\",\n      \"prompt\": \"Inject Corrupted Voltage / Negative IRQ Packet\"\n    }\n  ],\n  \"dependencies\": {\n    \"@react-three/fiber\": \"^9.0.0\",\n    \"three\": \"^0.173.0\",\n    \"zod\": \"^4.3.6\",\n    \"zustand\": \"^5.1.0\"\n  },\n  \"devDependencies\": {\n    \"@types/three\": \"^0.173.0\"\n  }\n}\n",
